public class Solution {

    private static volatile boolean running = true;

    public static boolean stops(int workers) {
        running = true;
        Thread[] spinning = new Thread[workers];
        for (int i = 0; i < workers; i++) {
            spinning[i] = new Thread(() -> {
                while (running) {
                    Thread.onSpinWait();
                }
            });
            spinning[i].start();
        }
        try {
            Thread.sleep(50);
            running = false;
            for (Thread worker : spinning) {
                worker.join(2000);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        }
        for (Thread worker : spinning) {
            if (worker.isAlive()) {
                return false;
            }
        }
        return true;
    }
}

