import java.util.List;
import java.util.concurrent.locks.ReentrantLock;

public class Solution {

    private static final class Account {

        private final int id;
        private final ReentrantLock lock = new ReentrantLock();
        private int balance;

        Account(int id, int balance) {
            this.id = id;
            this.balance = balance;
        }
    }

    public static List<Integer> transfer(int rounds) {
        Account first = new Account(1, 100);
        Account second = new Account(2, 100);
        Thread forwards = new Thread(() -> move(first, second, rounds));
        Thread backwards = new Thread(() -> move(second, first, rounds));
        forwards.start();
        backwards.start();
        try {
            forwards.join();
            backwards.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return List.of(first.balance, second.balance);
    }

    private static void move(Account from, Account to, int rounds) {
        Account lower = from.id < to.id ? from : to;
        Account higher = lower == from ? to : from;
        for (int round = 0; round < rounds; round++) {
            lower.lock.lock();
            try {
                higher.lock.lock();
                try {
                    from.balance--;
                    to.balance++;
                } finally {
                    higher.lock.unlock();
                }
            } finally {
                lower.lock.unlock();
            }
        }
    }
}

