import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

public class Solution {

    public static List<String> counts(String[] words, int threads) {
        Map<String, Integer> counted = new ConcurrentHashMap<>();
        Thread[] workers = new Thread[threads];
        for (int worker = 0; worker < threads; worker++) {
            int offset = worker;
            workers[worker] = new Thread(() -> {
                for (int i = offset; i < words.length; i += threads) {
                    counted.merge(words[i], 1, Integer::sum);
                }
            });
            workers[worker].start();
        }
        for (Thread worker : workers) {
            try {
                worker.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        List<String> sorted = new ArrayList<>();
        new TreeMap<>(counted).forEach((word, count) -> sorted.add(word + "=" + count));
        return sorted;
    }
}

