import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

public class Solution {

    public static String run(int tasks) {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        long sum = 0;
        try {
            List<Future<Long>> pending = new ArrayList<>();
            for (int i = 1; i <= tasks; i++) {
                long value = i;
                pending.add(pool.submit(() -> value * value));
            }
            for (Future<Long> future : pending) {
                sum += future.get();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "interrupted";
        } catch (ExecutionException e) {
            return "failed";
        } finally {
            pool.shutdown();
        }
        boolean terminated;
        try {
            terminated = pool.awaitTermination(2, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            terminated = false;
        }
        return "sum=" + sum + ",terminated=" + terminated;
    }
}

