import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class Solution {

    public static List<String> pipeline(int[] inputs) {
        List<CompletableFuture<String>> stages = new ArrayList<>();
        for (int input : inputs) {
            int value = input;
            stages.add(CompletableFuture
                    .supplyAsync(() -> {
                        if (value < 0) {
                            throw new IllegalArgumentException("negative: " + value);
                        }
                        return value * 2;
                    })
                    .thenApply(doubled -> "ok:" + doubled)
                    .exceptionally(failure -> "fallback:" + failure.getCause().getMessage()));
        }
        List<String> results = new ArrayList<>();
        for (CompletableFuture<String> stage : stages) {
            results.add(stage.join());
        }
        return results;
    }
}

