import java.util.concurrent.atomic.AtomicInteger;

public class Solution {

    public static int max(int[] values, int threads) {
        AtomicInteger largest = new AtomicInteger(Integer.MIN_VALUE);
        Thread[] workers = new Thread[threads];
        for (int worker = 0; worker < threads; worker++) {
            int offset = worker;
            workers[worker] = new Thread(() -> {
                for (int i = offset; i < values.length; i += threads) {
                    int candidate = values[i];
                    int current = largest.get();
                    while (candidate > current && !largest.compareAndSet(current, candidate)) {
                        current = largest.get();
                    }
                }
            });
            workers[worker].start();
        }
        for (Thread worker : workers) {
            try {
                worker.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return largest.get();
    }
}

